interface UserProfile {
  name: string;
  email: string;
  city: string;
}

export function ProfileForm() {
  const [user, setUser] = useState<UserProfile>({
    name: "طارق",
    email: "tarek@example.com",
    city: "القاهرة",
  });

  // غلط قاتل:
  function badUpdate() {
    user.city = "الإسكندرية"; // تعديل مباشر في الذاكرة (Mutation)
    setUser(user); // React مش هتحس بأي تغيير لأن الـ Reference هو هو!
  }

  // صح واحترافي: إنشاء نسخة جديدة تماماً باستخدام Spread Operator
  function goodUpdate(newCity: string) {
    setUser((prevUser) => ({
      ...prevUser, // بننسخ كل البيانات القديمة
      city: newCity, // بنعدل الخاصية المطلوبة فقط
    }));
  }

  return (
    <div>
      <p>{user.name} من {user.city}</p>
      <button onClick={() => goodUpdate("الإسكندرية")}>نقل للإسكندرية</button>
    </div>
  );
}

interface TodoItem {
  id: number;
  text: string;
  completed: boolean;
}

export function TodoList() {
  const [todos, setTodos] = useState<TodoItem[]>([
    { id: 1, text: "مذاكرة الفصل الأول من React", completed: true },
    { id: 2, text: "كتابة أول مكون تفاعلي", completed: false },
  ]);

  // 1. إضافة عنصر جديد (إضافة بالـ Spread بدل push)
  function addTodo(text: string) {
    const newTodo: TodoItem = { id: Date.now(), text, completed: false };
    setTodos((prevTodos) => [...prevTodos, newTodo]);
  }

  // 2. حذف عنصر (استخدام filter لإنتاج مصفوفة جديدة)
  function deleteTodo(idToDelete: number) {
    setTodos((prevTodos) => prevTodos.filter((todo) => todo.id !== idToDelete));
  }

  // 3. تعديل عنصر (استخدام map لإنتاج مصفوفة جديدة)
  function toggleTodo(idToToggle: number) {
    setTodos((prevTodos) =>
      prevTodos.map((todo) =>
        todo.id === idToToggle ? { ...todo, completed: !todo.completed } : todo
      )
    );
  }

  return (
    <div>
      <h3>قائمة المهام ({todos.length})</h3>
      {/* رندرة القائمة */}
    </div>
  );
}

