interface UserProfileProps {
  isLoading: boolean;
  error: string | null;
  user: { name: string; email: string } | null;
}

export function UserProfile({ isLoading, error, user }: UserProfileProps) {
  // 1. حالة التحميل
  if (isLoading) {
    return <div className="spinner">جاري تحميل البيانات...</div>;
  }

  // 2. حالة وجود خطأ
  if (error) {
    return <div className="error-alert">حدث خطأ: {error}</div>;
  }

  // 3. حالة عدم وجود بيانات (User is null)
  if (!user) {
    return <div className="empty-box">لم يتم العثور على بيانات المستخدم.</div>;
  }

  // 4. حالة النجاح الطبيعية (هنا TypeScript متأكد 100% إن user موجود ومش null)
  return (
    <div className="profile-card">
      <h2>{user.name}</h2>
      <p>{user.email}</p>
    </div>
  );
}

