type ApiResponse = 
  | { status: "loading" }
  | { status: "error"; message: string }
  | { status: "success"; data: { id: number; title: string }[] };

export function Feed({ response }: { response: ApiResponse }) {
  if (response.status === "loading") {
    return <p>جاري التحميل...</p>;
  }

  if (response.status === "error") {
    return <p className="text-red-500">{response.message}</p>;
  }

  // هنا TypeScript عارف تلقائياً إن response عنده data بس!
  return (
    <ul>
      {response.data.map((item) => (
        <li key={item.id}>{item.title}</li>
      ))}
    </ul>
  );
}

