  id: string; // أو number المهم يكون فريد ومستقر
  title: string;
  author: string;
  readTime: number;
}

interface ArticleListProps {
  articles: Article[];
}

export function ArticleList({ articles }: ArticleListProps) {
  // التعامل مع القائمة الفارغة أولاً
  if (articles.length === 0) {
    return <p className="text-gray-500">لا توجد مقالات منشورة حالياً.</p>;
  }

  return (
    <div className="article-feed">
      <h2>أحدث المقالات</h2>
      <ul>
        {articles.map((article) => (
          // الـ key لازم يتحط على العنصر الخارجي المباشر الناتج من الـ map
          <li key={article.id} className="article-item">
            <h3>{article.title}</h3>
            <p>الكاتب: {article.author} • {article.readTime} دقائق قراءة</p>
          </li>
        ))}
      </ul>
    </div>
  );
}

