import React, { useState } from "react";

interface FormData {
  fullName: string;
  email: string;
  role: string;
  newsletter: boolean;
}

interface FormErrors {
  fullName?: string;
  email?: string;
}

export function RegistrationForm() {
  const [formData, setFormData] = useState<FormData>({
    fullName: "",
    email: "",
    role: "developer",
    newsletter: false,
  });

  const [errors, setErrors] = useState<FormErrors>({});
  const [isSubmitting, setIsSubmitting] = useState(false);

  // دالة معالجة عامة لكل الحقول باستخدام خاصية name
  function handleChange(
    e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>
  ) {
    const { name, value, type } = e.target;

    // فحص لو كان الحقل checkbox
    const fieldValue =
      type === "checkbox"
        ? (e.target as HTMLInputElement).checked
        : value;

    setFormData((prev) => ({
      ...prev,
      [name]: fieldValue,
    }));
  }

  // التحقق من صحة البيانات (Validation)
  function validate(): boolean {
    const newErrors: FormErrors = {};

    if (!formData.fullName.trim()) {
      newErrors.fullName = "الاسم بالكامل مطلوب";
    } else if (formData.fullName.length < 3) {
      newErrors.fullName = "الاسم يجب ألا يقل عن 3 أحرف";
    }

    if (!formData.email.includes("@")) {
      newErrors.email = "بريد إلكتروني غير صالح";
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  }

  async function handleSubmit(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault();
    if (!validate()) return;

    setIsSubmitting(true);
    try {
      // محاكاة إرسال للـ API
      console.log("جاري إرسال البيانات المعتمدة:", formData);
      await new Promise((resolve) => setTimeout(resolve, 1500));
      alert("تم التسجيل بنجاح!");
      // تفريغ الفورم
      setFormData({
        fullName: "",
        email: "",
        role: "developer",
        newsletter: false,
      });
      setErrors({});
    } finally {
      setIsSubmitting(false);
    }
  }

  return (
    <form onSubmit={handleSubmit} className="form-box">
      {/* حقل الاسم */}
      <div className="form-group">
        <label>الاسم الكامل</label>
        <input
          type="text"
          name="fullName"
          value={formData.fullName}
          onChange={handleChange}
        />
        {errors.fullName && <span className="error-text">{errors.fullName}</span>}
      </div>

      {/* حقل البريد */}
      <div className="form-group">
        <label>البريد الإلكتروني</label>
        <input
          type="email"
          name="email"
          value={formData.email}
          onChange={handleChange}
        />
        {errors.email && <span className="error-text">{errors.email}</span>}
      </div>

      {/* القائمة المنسدلة */}
      <div className="form-group">
        <label>الوظيفة</label>
        <select name="role" value={formData.role} onChange={handleChange}>
          <option value="developer">مطور برمجيات</option>
          <option value="designer">مصمم واجهات</option>
          <option value="manager">مدير مشروع</option>
        </select>
      </div>

      {/* الشيك بوكس */}
      <div className="form-group-checkbox">
        <label>
          <input
            type="checkbox"
            name="newsletter"
            checked={formData.newsletter}
            onChange={handleChange}
          />
          الاشتراك في النشرة البريدية
        </label>
      </div>

      {/* زر الإرسال مع حالة التحميل */}
      <button type="submit" disabled={isSubmitting} className="submit-btn">
        {isSubmitting ? "جاري الحفظ..." : "إنشاء حساب"}
      </button>
    </form>
  );
}

