// src/components/Calculator.tsx
import { useState } from "react";
import { TemperatureInput } from "./TemperatureInput";

function toCelsius(fahrenheit: number) {
  return ((fahrenheit - 32) * 5) / 9;
}

function toFahrenheit(celsius: number) {
  return (celsius * 9) / 5 + 32;
}

function tryConvert(temperature: string, convert: (n: number) => number) {
  const input = parseFloat(temperature);
  if (Number.isNaN(input)) return "";
  const output = convert(input);
  const rounded = Math.round(output * 1000) / 1000;
  return rounded.toString();
}

export function TemperatureCalculator() {
  // الـ State موجود في الأب المشترك بس
  const [temperature, setTemperature] = useState("");
  const [scale, setScale] = useState<"c" | "f">("c");

  function handleCelsiusChange(val: string) {
    setScale("c");
    setTemperature(val);
  }

  function handleFahrenheitChange(val: string) {
    setScale("f");
    setTemperature(val);
  }

  // حساب القيم المشتقة (Derived State) من غير تكرار الـ State
  const celsius = scale === "f" ? tryConvert(temperature, toCelsius) : temperature;
  const fahrenheit = scale === "c" ? tryConvert(temperature, toFahrenheit) : temperature;

  return (
    <div className="max-w-md mx-auto p-4 bg-white shadow rounded">
      <h2 className="text-xl font-bold mb-4">محول درجات الحرارة</h2>
      <TemperatureInput
        scale="c"
        temperature={celsius}
        onTemperatureChange={handleCelsiusChange}
      />
      <TemperatureInput
        scale="f"
        temperature={fahrenheit}
        onTemperatureChange={handleFahrenheitChange}
      />
    </div>
  );
}

