import { useEffect, useState } from "react";

export function WindowWidthTracker() {
  const [width, setWidth] = useState(window.innerWidth);

  useEffect(() => {
    function handleResize() {
      setWidth(window.innerWidth);
    }

    // 1. الاشتراك في الحدث الخارجي
    window.addEventListener("resize", handleResize);
    console.log("تم تفعيل مراقبة حجم الشاشة");

    // 2. دالة التنظيف الإجبارية لمنع Memory Leak
    return () => {
      window.removeEventListener("resize", handleResize);
      console.log("تم إلغاء المراقبة وتنظيف الذاكرة بنجاح");
    };
  }, []); // مصفوفة فاضية لأننا بنشترك مرة واحدة عند الـ Mount

  return <h2>عرض الشاشة الحالي: {width}px</h2>;
}

