import { useRef, useEffect } from "react";

export function AutoFocusInput() {
  // بنعرف الـ Ref ونحدد نوع عنصر الـ HTML في TypeScript
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    // تركيز مؤشر الكتابة فور نزول المكون على الشاشة
    inputRef.current?.focus();
  }, []);

  function handleClear() {
    if (inputRef.current) {
      inputRef.current.value = "";
      inputRef.current.focus();
    }
  }

  return (
    <div className="p-4">
      <input
        ref={inputRef} // ربط الـ Ref بعنصر الـ DOM الحقيقي
        type="text"
        placeholder="اكتب هنا..."
        className="border p-2 rounded"
      />
      <button onClick={handleClear} className="ml-2 bg-gray-200 p-2 rounded">
        مسح وتركيز
      </button>
    </div>
  );
}

