import { useState, useRef } from "react";

export function Stopwatch() {
  const [seconds, setSeconds] = useState(0);
  const [isRunning, setIsRunning] = useState(false);

  // تخزين معرف الـ Interval من غير التسبب في Re-render عند حفظه
  const timerIdRef = useRef<number | null>(null);

  function start() {
    if (isRunning) return;
    setIsRunning(true);
    // حفظ الـ ID في الـ ref.current
    timerIdRef.current = window.setInterval(() => {
      setSeconds((prev) => prev + 1);
    }, 1000);
  }

  function stop() {
    if (timerIdRef.current !== null) {
      clearInterval(timerIdRef.current);
      timerIdRef.current = null;
    }
    setIsRunning(false);
  }

  function reset() {
    stop();
    setSeconds(0);
  }

  return (
    <div className="text-center p-4">
      <h1 className="text-4xl font-mono mb-4">{seconds}s</h1>
      <div className="space-x-2">
        <button onClick={start} disabled={isRunning} className="btn-start">بدء</button>
        <button onClick={stop} disabled={!isRunning} className="btn-stop">إيقاف</button>
        <button onClick={reset} className="btn-reset">تصفير</button>
      </div>
    </div>
  );
}

