import { useState } from "react";

export function useToggle(initialValue: boolean = false): [boolean, () => void, (val: boolean) => void] {
  const [value, setValue] = useState<boolean>(initialValue);

  function toggle() {
    setValue((prev) => !prev);
  }

  return [value, toggle, setValue];
}

// src/hooks/useLocalStorage.ts
import { useState, useEffect } from "react";

export function useLocalStorage<T>(key: string, initialValue: T): [T, (val: T | ((prev: T) => T)) => void] {
  // 1. قراءة القيمة الأولية من المتصفح بأمان
  const [storedValue, setStoredValue] = useState<T>(() => {
    try {
      const item = window.localStorage.getItem(key);
      return item ? (JSON.parse(item) as T) : initialValue;
    } catch (error) {
      console.error(`خطأ في قراءة ${key} من localStorage:`, error);
      return initialValue;
    }
  });

  // 2. مزامنة أي تغيير مع localStorage
  useEffect(() => {
    try {
      window.localStorage.setItem(key, JSON.stringify(storedValue));
    } catch (error) {
      console.error(`خطأ في حفظ ${key} في localStorage:`, error);
    }
  }, [key, storedValue]);

  return [storedValue, setStoredValue];
}

import { useLocalStorage } from "./hooks/useLocalStorage";

interface Settings {
  theme: "light" | "dark";
  notifications: boolean;
}

export function AppSettings() {
  const [settings, setSettings] = useLocalStorage<Settings>("user_settings", {
    theme: "light",
    notifications: true,
  });

  function toggleTheme() {
    setSettings((prev) => ({
      ...prev,
      theme: prev.theme === "light" ? "dark" : "light",
    }));
  }

  return (
    <div className={`p-4 ${settings.theme === "dark" ? "bg-gray-900 text-white" : "bg-white"}`}>
      <p>الوضع الحالي: {settings.theme}</p>
      <button onClick={toggleTheme} className="btn-toggle">
        تبديل الوضع
      </button>
    </div>
  );
}

