// src/context/ThemeContext.tsx
import React, { createContext, useContext, useState, ReactNode } from "react";

type Theme = "light" | "dark";

interface ThemeContextType {
  theme: Theme;
  toggleTheme: () => void;
}

// 1. إنشاء الـ Context مع قيمة مبدئية undefined لحمايته
const ThemeContext = createContext<ThemeContextType | undefined>(undefined);

// 2. المكون الموفر المخصص (Custom Provider Component)
export function ThemeProvider({ children }: { children: ReactNode }) {
  const [theme, setTheme] = useState<Theme>("light");

  function toggleTheme() {
    setTheme((prev) => (prev === "light" ? "dark" : "light"));
  }

  const value: ThemeContextType = {
    theme,
    toggleTheme,
  };

  return (
    <ThemeContext.Provider value={value}>
      {children}
    </ThemeContext.Provider>
  );
}

// 3. الخطاف المخصص الآمن (Custom Consumer Hook)
export function useTheme(): ThemeContextType {
  const context = useContext(ThemeContext);
  if (!context) {
    throw new Error("لازم استخدام useTheme داخل <ThemeProvider> حصراً!");
  }
  return context;
}

