// src/components/UserList.tsx
import { useState, useEffect } from "react";

interface User {
  id: number;
  name: string;
  email: string;
  company: { name: string };
}

export function UserList() {
  const [users, setUsers] = useState<User[]>([]);
  const [isLoading, setIsLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    // 1. إنشاء متحكم الإلغاء
    const controller = new AbortController();
    const { signal } = controller;

    async function fetchUsers() {
      try {
        setIsLoading(true);
        setError(null);

        const response = await fetch(
          "https://jsonplaceholder.typicode.com/users",
          { signal } // تمرير الإشارة لإلغاء الطلب إذا لزم الأمر
        );

        // فحص حالة الاستجابة في HTTP (404, 500, إلخ)
        if (!response.ok) {
          throw new Error(`فشل الاتصال بالسيرفر (كود: ${response.status})`);
        }

        const data: User[] = await response.json();
        setUsers(data);
      } catch (err: unknown) {
        // تجاهل الخطأ لو كان سببه إلغاء الطلب المقصود عند unmount
        if (err instanceof Error && err.name === "AbortError") {
          console.log("تم إلغاء الطلب السابق بأمان");
          return;
        }

        const errorMessage =
          err instanceof Error ? err.message : "حدث خطأ غير متوقع";
        setError(errorMessage);
      } finally {
        setIsLoading(false);
      }
    }

    fetchUsers();

    // 2. دالة التنظيف: إلغاء الطلب فوراً لو المكون اتمسح أو الـ Dependencies اتغيرت
    return () => {
      controller.abort();
    };
  }, []);

  // 1. رندرة حالة التحميل
  if (isLoading) {
    return <div className="p-4 text-blue-600 font-bold">جاري تحميل المستخدمين...</div>;
  }

  // 2. رندرة حالة الخطأ مع زر إعادة المحاولة
  if (error) {
    return (
      <div className="p-4 text-red-600 bg-red-50 rounded">
        <p>خطأ: {error}</p>
        <button onClick={() => window.location.reload()} className="mt-2 text-sm underline">
          إعادة المحاولة
        </button>
      </div>
    );
  }

  // 3. رندرة الحالة الفارغة
  if (users.length === 0) {
    return <div className="p-4 text-gray-500">لا يوجد مستخدمون مسجلون.</div>;
  }

  // 4. رندرة حالة النجاح
  return (
    <div className="p-4">
      <h2 className="text-xl font-bold mb-4">قائمة المستخدمين ({users.length})</h2>
      <ul className="space-y-2">
        {users.map((user) => (
          <li key={user.id} className="p-3 border rounded hover:bg-gray-50">
            <h3 className="font-semibold">{user.name}</h3>
            <p className="text-sm text-gray-600">{user.email} • {user.company.name}</p>
          </li>
        ))}
      </ul>
    </div>
  );
}

