import React, { useState } from "react";
import { useMutation, useQueryClient } from "@tanstack/react-query";

interface NewProduct {
  title: string;
  price: number;
}

async function createProductApi(newProduct: NewProduct) {
  const res = await fetch("https://fakestoreapi.com/products", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(newProduct),
  });
  if (!res.ok) throw new Error("فشل إنشاء المنتج");
  return await res.json();
}

export function AddProductForm() {
  const [title, setTitle] = useState("");
  const [price, setPrice] = useState("");

  const queryClient = useQueryClient();

  const mutation = useMutation({
    mutationFn: createProductApi,
    // عند نجاح العملية على السيرفر:
    onSuccess: () => {
      // إبطال كاش المنتجات القديم ليتم إعادة جلبه تلقائياً بالمنتج الجديد!
      queryClient.invalidateQueries({ queryKey: ["products"] });
      setTitle("");
      setPrice("");
      alert("تمت إضافة المنتج بنجاح وتحديث الكاش!");
    },
    onError: (err) => {
      alert(`خطأ: ${err.message}`);
    },
  });

  function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    if (!title || !price) return;
    mutation.mutate({ title, price: Number(price) });
  }

  return (
    <form onSubmit={handleSubmit} className="p-4 border rounded mb-6">
      <h3 className="font-bold mb-2">إضافة منتج جديد</h3>
      <input
        type="text"
        placeholder="اسم المنتج"
        value={title}
        onChange={(e) => setTitle(e.target.value)}
        className="border p-2 rounded mr-2"
      />
      <input
        type="number"
        placeholder="السعر"
        value={price}
        onChange={(e) => setPrice(e.target.value)}
        className="border p-2 rounded mr-2"
      />
      <button
        type="submit"
        disabled={mutation.isPending}
        className="bg-green-600 text-white px-4 py-2 rounded"
      >
        {mutation.isPending ? "جاري الإرسال..." : "إضافة المنتج"}
      </button>
    </form>
  );
}

