  console.log("بدء حساب إحصائيات معقدة جداً...");
  // عملية بتاخد وقت مع آلاف الأرقام
  return data.reduce((acc, val) => acc + Math.sqrt(val) * Math.sin(val), 0);
}

export function StatsViewer({ dataset }: { dataset: number[] }) {
  const [theme, setTheme] = useState("light");

  // الحساب هيتنفذ بس لما dataset تتغير، ومش هيتنفذ عند تبديل الـ theme
  const computedTotal = useMemo(() => {
    return calculateHeavyStats(dataset);
  }, [dataset]);

  return (
    <div className={theme}>
      <h2>الإحصائية المحسوبة: {computedTotal}</h2>
      <button onClick={() => setTheme(theme === "light" ? "dark" : "light")}>
        تبديل الثيم
      </button>
    </div>
  );
}

