// src/components/ErrorBoundary.tsx
import React, { Component, ErrorInfo, ReactNode } from "react";

interface Props {
  children: ReactNode;
  fallback?: ReactNode;
}

interface State {
  hasError: boolean;
  error: Error | null;
}

export class ErrorBoundary extends Component<Props, State> {
  public state: State = {
    hasError: false,
    error: null,
  };

  // 1. تحديث الحالة لرسم الـ Fallback UI في الرندرة القادمة
  public static getDerivedStateFromError(error: Error): State {
    return { hasError: true, error };
  }

  // 2. تسجيل الخطأ لخدمات المراقبة (زي Sentry)
  public componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    console.error("تم اصطياد خطأ في React:", error, errorInfo);
  }

  public render() {
    if (this.state.hasError) {
      // إما عرض Fallback مخصص تم تمريره أو واجهة افتراضية
      return (
        this.props.fallback || (
          <div className="p-4 bg-red-50 border border-red-200 rounded text-center">
            <h3 className="text-red-700 font-bold">عفواً، حدث خطأ غير متوقع في هذا الجزء!</h3>
            <p className="text-sm text-red-500 mt-1">{this.state.error?.message}</p>
            <button
              onClick={() => this.setState({ hasError: false, error: null })}
              className="mt-3 bg-red-600 text-white px-3 py-1 rounded text-sm"
            >
              إعادة المحاولة
            </button>
          </div>
        )
      );
    }

    return this.props.children;
  }
}

