// تصميم خصائص ذكي ومحمي:
type ButtonVariantProps =
  | {
      variant: "action";
      onClick: () => void;
      isLoading?: boolean;
    }
  | {
      variant: "link";
      href: string;
      target?: "_blank" | "_self";
    };

type ButtonProps = ButtonVariantProps & {
  children: React.ReactNode;
  className?: string;
};

export function CustomButton(props: ButtonProps) {
  if (props.variant === "link") {
    // هنا TypeScript متأكد 100% إن href موجود ومستحيل يطلب onClick!
    return (
      <a href={props.href} target={props.target} className={props.className}>
        {props.children}
      </a>
    );
  }

  // هنا TypeScript متأكد إن onClick و isLoading متاحين!
  return (
    <button
      onClick={props.onClick}
      disabled={props.isLoading}
      className={props.className}
    >
      {props.isLoading ? "جاري التحميل..." : props.children}
    </button>
  );
}

