// src/routes/ProtectedRoute.tsx
import { Navigate, useLocation } from "react-router-dom";
import { useAuth } from "../context/AuthContext";

interface ProtectedRouteProps {
  children: JSX.Element;
  requiredRole?: "user" | "admin";
}

export function ProtectedRoute({ children, requiredRole }: ProtectedRouteProps) {
  const { user, isAuthenticated, isLoading } = useAuth();
  const location = useLocation();

  // 1. أثناء فحص الجلسة، نعرض شاشة تحميل لمنع التوجيه الخاطئ
  if (isLoading) {
    return <div className="screen-loader">جاري التحقق من هوية المستخدم...</div>;
  }

  // 2. لو لم يكن مسجل دخول، يتم توجيهه لصفحة الدخول
  if (!isAuthenticated) {
    return <Navigate to="/login" state={{ from: location }} replace />;
  }

  // 3. لو كان المسار يتطلب صلاحيات معينة (Role Guard)
  if (requiredRole && user?.role !== requiredRole) {
    return <div className="p-8 text-center text-red-600">عفواً، ليس لديك صلاحية لدخول هذه الصفحة (Admin Only).</div>;
  }

  return children;
}

