import { render, screen } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { describe, it, expect } from "vitest";
import { Counter } from "./Counter";

describe("مكون العداد (Counter Component)", () => {
  it("يعرض القيمة المبدئية 0 بشكل صحيح عند الفتح", () => {
    render(<Counter />);
    expect(screen.getByText("العدد: 0")).toBeInTheDocument();
  });

  it("يقوم بزيادة العداد بمقدار 1 عند النقر على زر زيادة", async () => {
    // 1. تجهيز الـ userEvent
    const user = userEvent.setup();
    render(<Counter />);

    // 2. الوصول للعنصر بنفس طريقة المستخدم
    const incrementBtn = screen.getByRole("button", { name: "زيادة" });

    // 3. محاكاة النقر
    await user.click(incrementBtn);

    // 4. التحقق من النتيجة المتوقعة على الشاشة
    expect(screen.getByText("العدد: 1")).toBeInTheDocument();
  });

  it("يقوم بتصفير العداد عند النقر على زر تصفير", async () => {
    const user = userEvent.setup();
    render(<Counter />);

    const incrementBtn = screen.getByRole("button", { name: "زيادة" });
    const resetBtn = screen.getByRole("button", { name: "تصفير" });

    await user.click(incrementBtn);
    await user.click(incrementBtn);
    expect(screen.getByText("العدد: 2")).toBeInTheDocument();

    await user.click(resetBtn);
    expect(screen.getByText("العدد: 0")).toBeInTheDocument();
  });
});

