  const userName = await screen.findByText("أحمد علي", {}, { timeout: 3000 });
  expect(userName).toBeInTheDocument();

  // 3. التأكد من اختفاء شاشة التحميل
  expect(screen.queryByText(/جاري التحميل/i)).not.toBeInTheDocument();
});

