// src/features/addresses/api/addressApi.ts
import { apiClient } from "../../../services/apiClient";
import { Address, CreateAddressDTO } from "../types";

export async function fetchAddresses(): Promise<Address[]> {
  return apiClient.get("/user/addresses");
}

export async function addAddress(data: CreateAddressDTO): Promise<Address> {
  return apiClient.post("/user/addresses", data);
}

// src/features/addresses/hooks/useAddresses.ts
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { fetchAddresses, addAddress } from "../api/addressApi";

export function useAddresses() {
  const queryClient = useQueryClient();

  const query = useQuery({
    queryKey: ["user-addresses"],
    queryFn: fetchAddresses,
  });

  const createMutation = useMutation({
    mutationFn: addAddress,
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["user-addresses"] });
    },
  });

  return {
    addresses: query.data || [],
    isLoading: query.isLoading,
    isError: query.isError,
    createAddress: createMutation.mutate,
    isCreating: createMutation.isPending,
  };
}

// src/features/addresses/components/AddressList.tsx
import { useAddresses } from "../hooks/useAddresses";
import { Button } from "../../../components/ui/Button";

export function AddressList() {
  const { addresses, isLoading, isError } = useAddresses();

  if (isLoading) return <p>جاري تحميل العناوين...</p>;
  if (isError) return <p className="text-red-500">حدث خطأ أثناء تحميل العناوين.</p>;

  return (
    <div className="space-y-3">
      <h3 className="text-lg font-bold">عناويني المسجلة</h3>
      {addresses.map((addr) => (
        <div key={addr.id} className="p-3 border rounded flex justify-between">
          <div>
            <p className="font-semibold">{addr.street}</p>
            <p className="text-sm text-gray-600">{addr.city}</p>
          </div>
          {addr.isDefault && <span className="text-xs bg-green-100 text-green-700 px-2 py-1 rounded">افتراضي</span>}
        </div>
      ))}
    </div>
  );
}

